class Solution:
    def numberOfWays(self, n: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (n + 1)
        dp[0] = 1
        for coin in (1, 2):
            for s in range(coin, n + 1):
                dp[s] = (dp[s] + dp[s - coin]) % MOD
        snap = dp[:]
        for s in range(4, n + 1):
            dp[s] = (dp[s] + snap[s - 4] + (snap[s - 8] if s >= 8 else 0)) % MOD
        for s in range(6, n + 1):
            dp[s] = (dp[s] + dp[s - 6]) % MOD
        return dp[n]

