class Solution {
public:
    int numberOfWays(int n) {
        const int MOD = 1e9 + 7;
        vector<long long> dp(n + 1, 0);
        dp[0] = 1;
        for (int coin : {1, 2})
            for (int s = coin; s <= n; s++)
                dp[s] = (dp[s] + dp[s - coin]) % MOD;
        vector<long long> snap = dp;
        for (int s = 4; s <= n; s++) {
            dp[s] = (dp[s] + snap[s - 4]) % MOD;
            if (s >= 8) dp[s] = (dp[s] + snap[s - 8]) % MOD;
        }
        for (int s = 6; s <= n; s++)
            dp[s] = (dp[s] + dp[s - 6]) % MOD;
        return dp[n];
    }
};

