class Solution {
    public int numberOfWays(int n) {
        final int MOD = 1_000_000_007;
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int coin : new int[]{1, 2})
            for (int s = coin; s <= n; s++)
                dp[s] = (dp[s] + dp[s - coin]) % MOD;
        long[] snap = dp.clone();
        for (int s = 4; s <= n; s++) {
            dp[s] = (dp[s] + snap[s - 4]) % MOD;
            if (s >= 8) dp[s] = (dp[s] + snap[s - 8]) % MOD;
        }
        for (int s = 6; s <= n; s++)
            dp[s] = (dp[s] + dp[s - 6]) % MOD;
        return (int) dp[n];
    }
}

