var numberOfWays = function(n) {
    const MOD = 1e9 + 7;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    for (const coin of [1, 2])
        for (let s = coin; s <= n; s++)
            dp[s] = (dp[s] + dp[s - coin]) % MOD;
    const snap = dp.slice();
    for (let s = 4; s <= n; s++) {
        dp[s] = (dp[s] + snap[s - 4]) % MOD;
        if (s >= 8) dp[s] = (dp[s] + snap[s - 8]) % MOD;
    }
    for (let s = 6; s <= n; s++)
        dp[s] = (dp[s] + dp[s - 6]) % MOD;
    return dp[n];
};
